ALTER TABLE public.license_sales ADD COLUMN IF NOT EXISTS discount_starts_on date;
ALTER TABLE public.license_sales ADD COLUMN IF NOT EXISTS discount_ends_on date;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='license_sale_discount_window') THEN ALTER TABLE public.license_sales ADD CONSTRAINT license_sale_discount_window CHECK ((discount_starts_on IS NULL AND discount_ends_on IS NULL) OR (discount_starts_on IS NOT NULL AND discount_ends_on IS NOT NULL AND discount_starts_on>=starts_on AND discount_ends_on>=discount_starts_on AND list_sale_price IS NOT NULL AND extract(day from discount_starts_on) IN (1,16) AND (extract(day from discount_ends_on)=15 OR discount_ends_on=(date_trunc('month',discount_ends_on)+interval '1 month - 1 day')::date))); END IF; END $$;
COMMENT ON COLUMN public.license_sales.discount_starts_on IS 'Inclusive temporary VK discount start in half-month steps; NULL preserves legacy permanent sale_price';
COMMENT ON COLUMN public.license_sales.discount_ends_on IS 'Inclusive temporary VK discount end; EK never changes';
CREATE OR REPLACE FUNCTION public.license_discount_period_amount(p_sale numeric,p_list numeric,p_quantity integer,p_start date,p_end date,p_cadence text,p_from date,p_to date) RETURNS numeric LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ DECLARE m date; h date; z date; v numeric:=0; rate numeric; BEGIN IF p_from IS NULL OR p_to IS NULL THEN RETURN public.license_period_amount(p_sale,p_quantity,p_start,p_end,p_cadence); END IF; IF p_cadence='once' THEN RETURN round((CASE WHEN p_start BETWEEN p_from AND p_to THEN p_sale ELSE p_list END)*p_quantity,2); END IF; m:=date_trunc('month',p_start)::date; WHILE m<=p_end LOOP FOR i IN 0..1 LOOP h:=m+CASE WHEN i=0 THEN 0 ELSE 15 END; z:=CASE WHEN i=0 THEN m+14 ELSE (m+interval '1 month - 1 day')::date END; IF h<=p_end AND z>=p_start THEN rate:=CASE WHEN h<=p_to AND z>=p_from THEN p_sale ELSE p_list END; v:=v+rate*p_quantity/2; END IF; END LOOP; m:=(m+interval '1 month')::date; END LOOP; RETURN round(v,2); END $$;
CREATE OR REPLACE FUNCTION public.bill_catalog_license_sale(p_sale uuid,p_start date,p_supplement boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE s license_sales; e date; a numeric; b numeric; ref text; li jsonb; tn text; inv tenant_invoices; ci partner_customer_invoices; inserted integer; booking text;
BEGIN
 SELECT * INTO s FROM license_sales WHERE id=p_sale FOR UPDATE;
 IF NOT FOUND OR (s.ended_on IS NOT NULL AND p_start>s.ended_on) THEN RETURN; END IF;
 e:=license_period_end(p_start,s.cadence); IF s.ended_on IS NOT NULL THEN e:=least(e,s.ended_on); END IF;
 INSERT INTO license_billing_events(sale_id,period_start,period_end) VALUES(s.id,p_start,e) ON CONFLICT DO NOTHING; GET DIAGNOSTICS inserted=ROW_COUNT; IF inserted=0 THEN RETURN; END IF;
 SELECT name INTO tn FROM tenants WHERE id=s.tenant_id;
 a:=license_discount_period_amount(s.sale_price,s.list_sale_price,s.quantity,p_start,e,s.cadence,s.discount_starts_on,s.discount_ends_on); b:=license_period_amount(s.purchase_price,s.quantity,p_start,e,s.cadence);
 booking:=s.tenant_id||':'||left(s.request_id::text,24)||':'||p_start;
 li:=jsonb_build_array(jsonb_build_object('type','license','code',s.product_code,'sale_id',s.id,'label',s.label,'quantity',s.quantity,'unit_price',a/s.quantity,'amount',a,'period_start',p_start,'period_end',e,'discount_pct',s.customer_discount_pct,'discount_starts_on',s.discount_starts_on,'discount_ends_on',s.discount_ends_on,'list_unit_price',s.list_sale_price));
 IF s.partner_id IS NOT NULL THEN
 ref:='license-booking:'||s.partner_id||':'||booking; PERFORM pg_advisory_xact_lock(hashtextextended(ref,0)); SELECT * INTO ci FROM partner_customer_invoices WHERE source_ref=ref FOR UPDATE;
 IF FOUND AND ci.issued_at IS NULL AND ci.status='draft' THEN UPDATE partner_customer_invoices SET amount=amount+a,line_items=line_items||li,period_start=least(period_start,p_start),period_end=greatest(period_end,e),document_type=CASE WHEN amount+a>0 THEN 'invoice' ELSE 'subscription_notice' END WHERE id=ci.id;
 ELSE IF FOUND THEN ref:=ref||':'||s.id; END IF; INSERT INTO partner_customer_invoices(partner_id,tenant_id,source_ref,period_start,period_end,amount,line_items,document_type,payment_method) VALUES(s.partner_id,s.tenant_id,ref,p_start,e,a,li,CASE WHEN a>0 THEN 'invoice' ELSE 'subscription_notice' END,s.payment_method) ON CONFLICT(source_ref) DO NOTHING; END IF; a:=b;
 END IF;
 li:=jsonb_build_array(jsonb_build_object('type','license','code',s.product_code,'sale_id',s.id,'label',s.label||' – '||coalesce(tn,''),'quantity',s.quantity,'unit_price',a/s.quantity,'amount',a,'period_start',p_start,'period_end',e));
 IF s.partner_id IS NOT NULL AND NOT p_supplement THEN ref:='license-cycle:'||s.partner_id||':'||s.cadence||':'||p_start; ELSE ref:='license-booking:'||coalesce(s.partner_id::text,'direct')||':'||booking; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(ref,0)); SELECT * INTO inv FROM tenant_invoices WHERE source_ref=ref AND status<>'voided' FOR UPDATE;
 IF FOUND AND inv.issued_at IS NULL AND inv.lexware_invoice_id IS NULL AND inv.status='draft' THEN UPDATE tenant_invoices SET amount=amount+a,module_total=module_total+a,line_items=line_items||li,period_start=least(period_start,p_start),period_end=greatest(period_end,e),document_type=CASE WHEN amount+a>0 THEN 'invoice' ELSE 'subscription_notice' END WHERE id=inv.id;
 ELSE IF FOUND THEN ref:=ref||':'||s.id; END IF; INSERT INTO tenant_invoices(tenant_id,partner_id,source_ref,invoice_number,invoice_kind,status,document_type,period_start,period_end,amount,module_total,support_total,line_items) VALUES(s.tenant_id,s.partner_id,ref,'DRAFT',CASE WHEN p_supplement OR s.cadence='once' THEN 'one_time' ELSE 'recurring' END,'draft',CASE WHEN a>0 THEN 'invoice' ELSE 'subscription_notice' END,p_start,e,a,a,0,li); END IF;
 UPDATE license_sales SET next_period=CASE WHEN cadence='once' THEN NULL ELSE e+1 END WHERE id=s.id;
END $$;
REVOKE ALL ON FUNCTION public.bill_catalog_license_sale(uuid,date,boolean) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.bill_catalog_license_sale(uuid,date,boolean) TO service_role;
CREATE OR REPLACE FUNCTION public.finalize_license_sale_discount(p_tenant uuid,p_kind text,p_code text,p_quantity integer,p_cadence text,p_price numeric,p_start date,p_payment text,p_request uuid,p_discount numeric DEFAULT 0,p_discount_from date DEFAULT NULL,p_discount_to date DEFAULT NULL,p_reason text DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE t public.tenants; v_id uuid; v_price numeric; v_list numeric; v_label text; v_mods text[]; m text; individual boolean;
BEGIN
PERFORM pg_advisory_xact_lock(hashtextextended(p_request::text,0)); v_id:=public.preflight_license_sale(p_tenant,p_kind,p_code,p_quantity,p_cadence,p_price,p_start,p_payment,p_request); IF v_id IS NOT NULL THEN RETURN v_id; END IF;
SELECT * INTO t FROM public.tenants WHERE id=p_tenant AND deleted_at IS NULL FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Tenant fehlt'; END IF;
IF p_discount IS NULL OR p_discount<0 OR p_discount>100 THEN RAISE EXCEPTION 'Rabatt muss zwischen 0 und 100 Prozent liegen'; END IF;
IF p_kind='package' THEN SELECT CASE WHEN t.partner_id IS NULL THEN uvp ELSE ek END,uvp,name INTO v_price,v_list,v_label FROM public.pricing_packages WHERE code=p_code AND active AND NOT always_active; SELECT array_agg(module_code) INTO v_mods FROM public.pricing_package_modules WHERE package_code=p_code;
ELSE SELECT CASE WHEN t.partner_id IS NULL THEN coalesce(new_sale_uvp,uvp) ELSE ek END,coalesce(new_sale_uvp,uvp),CASE WHEN code='charge_point' THEN 'Ladeinfrastruktur je Ladepunkt' WHEN code='remote_support' THEN 'Remote-Support-Flatrate' WHEN code='setup' THEN 'Einrichtung (einmalig)' ELSE name END INTO v_price,v_list,v_label FROM public.pricing_unit_prices WHERE code=p_code; v_mods:=CASE WHEN p_code='charge_point' THEN ARRAY['ev_charging','adhoc_payment'] WHEN p_code='extra_location' THEN ARRAY['locations'] ELSE ARRAY[]::text[] END; END IF;
IF v_price IS NULL OR v_list IS NULL THEN RAISE EXCEPTION 'Katalogpreis fehlt'; END IF;
individual:=abs(round(v_list*(1-p_discount/100),2)-p_price)>0.004; IF individual AND length(trim(coalesce(p_reason,'')))<5 THEN RAISE EXCEPTION 'Abweichender Preis benötigt eine Begründung'; END IF;
FOREACH m IN ARRAY coalesce(v_mods,ARRAY[]::text[]) LOOP IF NOT EXISTS(SELECT 1 FROM public.tenant_modules WHERE tenant_id=p_tenant AND module_code=m AND is_enabled) THEN RAISE EXCEPTION 'Modul zuerst über Freigabeweg aktivieren: %',m; END IF; IF t.partner_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.partner_modules WHERE partner_id=t.partner_id AND module_code=m) THEN RAISE EXCEPTION 'Nicht im Partnerportfolio'; END IF; END LOOP;
INSERT INTO public.license_sales(tenant_id,partner_id,product_kind,product_code,label,quantity,cadence,payment_method,sale_price,purchase_price,starts_on,next_period,request_id,created_by,customer_discount_pct,list_sale_price,discount_starts_on,discount_ends_on,price_individual,price_reason) VALUES(p_tenant,t.partner_id,p_kind,p_code,v_label,p_quantity,p_cadence,p_payment,p_price,v_price,p_start,p_start,p_request,auth.uid(),p_discount,v_list,p_discount_from,p_discount_to,individual,CASE WHEN individual THEN p_reason ELSE NULL END) RETURNING id INTO v_id;
PERFORM public.bill_license_sale(v_id,p_start,true); RETURN v_id;
END $$;
REVOKE ALL ON FUNCTION public.finalize_license_sale_discount(uuid,text,text,integer,text,numeric,date,text,uuid,numeric,date,date,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.finalize_license_sale_discount(uuid,text,text,integer,text,numeric,date,text,uuid,numeric,date,date,text) TO authenticated;